begin;
reset role;
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000001','lesson1@example.com'),('00000000-0000-0000-0000-000000000002','lesson2@example.com');
insert into public.profiles(id) values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002');
select t.as_user('');
set role anon;
select t.must_fail($$select public.record_agent_lesson('user_correction','global','private','Private','Synthetic private detail','Keep private','')$$,'permission denied','anonymous callers cannot write globally visible lessons');
set role service_role;
select t.must_fail($$select public.record_agent_lesson('user_correction','global','private','Private','Synthetic private detail','Keep private','')$$,'permission denied','service bridge cannot use auth-null legacy write');
select public.record_agent_lesson_as('00000000-0000-0000-0000-000000000001','user_correction','global','private','Private','Synthetic private detail','Keep private','');
select t.must_fail($$select public.record_agent_lesson_as(null,'user_correction','global','private','Private','Synthetic','Keep private','')$$,'verified lesson owner required','bridge cannot create an ownerless lesson');
select t.must_fail($$select public.record_agent_lesson_as('00000000-0000-0000-0000-000000000003','user_correction','global','private','Private','Synthetic','Keep private','')$$,'verified lesson owner required','bridge requires an existing account owner');
reset role;
select t.ok((select count(*)=1 and bool_and(user_id='00000000-0000-0000-0000-000000000001') from public.agent_lessons),'scope named global does not make a user correction globally visible');
select t.as_user('00000000-0000-0000-0000-000000000002');
set role authenticated;
select t.ok((select count(*)=0 from public.agent_lessons),'another owner cannot read the bridge private lesson');
select t.must_fail($$select public.record_agent_lesson_as('00000000-0000-0000-0000-000000000001','user_correction','global','private','Private','Synthetic','Keep private','')$$,'permission denied','a signed-in user cannot select another lesson owner');
select public.record_agent_lesson('chat_caught','global','category','Private two','Synthetic two','Keep private','');
select public.record_agent_lesson('chat_caught','global','category','Private two','Synthetic updated','Keep private','');
select t.ok((select count(*)=1 and bool_and(user_id=auth.uid()) and max(times_seen)=2 from public.agent_lessons),'authenticated lessons dedupe only inside their owner');
reset role;
select t.as_user('');
set role service_role;
select public.agent_lessons_note_applied_as('00000000-0000-0000-0000-000000000002',array(select id from public.agent_lessons));
reset role;
select t.ok((select times_applied=0 from public.agent_lessons where user_id='00000000-0000-0000-0000-000000000001'),'lesson application cannot alter another owner private record');
select t.ok((select times_applied=1 from public.agent_lessons where user_id='00000000-0000-0000-0000-000000000002'),'bridge application count stays scoped to its verified owner');
rollback;
